async def act(page):
    """
    Navigate to the admin product reviews grid and count how many review entries mention the term "satisfied" (case-insensitive).
    Prints the integer count to stdout.

    Notes on knowledge-base helper functions:
    - Reviewed KB functions: get_dashboard_summary, generate_sales_summary_for_date_range, export_dashboard_snapshot,
      summarize_top_search_terms_across_store_views. All operate on the Dashboard and its widgets and do not provide
      navigation or parsing for the admin reviews grid. Therefore none are used.
    """
    # Navigate to the product reviews management page using a relative URL
    await page.goto('/index.php/admin/review/product/')
    # Wait for network activity to idle and allow dynamic content to render
    await page.wait_for_load_state('networkidle')
    await page.wait_for_timeout(800)

    result_count = 0

    # Heuristically locate a reviews table among accessible tables
    tables = page.get_by_role('table')
    try:
        table_count = await tables.count()
    except Exception:
        table_count = 0

    target_table = None
    for i in range(table_count):
        t = tables.nth(i)
        try:
            ttext = (await t.inner_text() or "").lower()
        except Exception:
            ttext = ""
        if any(k in ttext for k in ('review', 'reviews', 'nickname', 'summary', 'title', 'status', 'rating', 'customer')):
            target_table = t
            break

    if target_table is not None:
        rows = target_table.get_by_role('row')
        try:
            row_count = await rows.count()
        except Exception:
            row_count = 0
        # Skip header-like first row when detected
        start_index = 0
        if row_count > 0:
            try:
                first_row_text = (await rows.nth(0).inner_text() or "").lower()
            except Exception:
                first_row_text = ""
            if any(h in first_row_text for h in ('review', 'summary', 'rating', 'title', 'nickname', 'status', 'customer')):
                start_index = 1
        for r in range(start_index, row_count):
            try:
                row_text = (await rows.nth(r).inner_text() or "").lower()
            except Exception:
                row_text = ""
            if 'satisfied' in row_text:
                result_count += 1
    else:
        # Fallback: search the document's visible inner text for occurrences of the substring
        doc = page.get_by_role('document')
        try:
            doc_text = (await doc.inner_text() or "").lower()
        except Exception:
            doc_text = ""
        result_count = doc_text.count('satisfied')

    # Print only the numeric result so the harness can capture stdout
    print(result_count)

